const still=[];
for(const n of c.toCreate){ if(!cn.has(n)) still.push(n+' on Companies'); if(!pn.has(n)) still.push(n+' on People'); }
if(still.length){ throw new Error('Insert domains to Clayroots created columns the base does not show: '+still.join(', ')+'. Nothing was written.'); }
return [{ json: { created: c.toCreate.slice() } }];

// Prepare Rows: the rows Read Meta kept, minus the domains on the client's DNC table (counted,
// never landed), narrowed to the keys Check Columns approved. Tag from _meta goes on every row
// when it is set. A row carrying Public Emails gets an empty public_emails_clean so Clean
// Fields fills it. One {_empty:true} placeholder when nothing is left, so the close still runs.
const m=$('Read Meta').first().json; const c=$('Check Columns').first().json;
const dnc=new Set();
for(const it of $('Get DNC Domains').all()){ const j=it.json||{}; const d=String((j.fields&&j.fields.Domain)||j.Domain||'').trim().toLowerCase(); if(d) dnc.add(d); }
const writable=new Set(c.writable||[]);
const has=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
const out=[];
for(const r of (m.rows||[])){
  if(dnc.has(r.Domain)) continue;
  const o={}; for(const k of Object.keys(r)){ if(writable.has(k)) o[k]=r[k]; }
  if(has(o,'Public Emails')&&!has(o,'public_emails_clean')) o.public_emails_clean='';
  if(m.tag) o.Tag=m.tag;
  out.push({ json: o });
}
if(!out.length) return [{ json: { _empty: true } }];
return out;

// Existing Filters: which of these domains Companies already holds, read before the upsert so
// Domain Source is written on create only. One OR formula per 100 domains keeps every request
// under Airtable's URL limit; Read Existing runs once per item and returns all pages.
const d=$input.all().map(i=>String((i.json||{}).Domain||'')).filter(Boolean);
const esc=(s)=>String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const out=[];
for(let i=0;i<d.length;i+=100){
  const chunk=d.slice(i,i+100);
  out.push({ json: { formula: chunk.length===1?("{Domain}='"+esc(chunk[0])+"'"):('OR('+chunk.map(x=>"{Domain}='"+esc(x)+"'").join(',')+')') } });
}
if(!out.length) out.push({ json: { formula: "{Domain}=''" } });
return out;

// Mark Source: the cleaned rows become the upsert items. A domain Companies already holds keeps
// its Domain Source (the key is removed from the row); a new domain gets _meta.domainSource.
// Every "_" carrier is stripped so the upsert sends columns only.
const m=$('Read Meta').first().json;
const existing=new Set();
for(const it of $('Read Existing').all()){ const j=it.json||{}; const d=String((j.fields&&j.fields.Domain)||j.Domain||'').trim().toLowerCase(); if(d) existing.add(d); }
const out=[];
for(const it of $('Clean Fields').all()){
  const r=Object.assign({}, it.json||{});
  for(const k of Object.keys(r)){ if(k.charAt(0)==='_') delete r[k]; }
  if(!r.Domain) continue;
  if(existing.has(String(r.Domain).toLowerCase())) delete r['Domain Source']; else r['Domain Source']=m.domainSource;
  out.push({ json: r });
}
return out;

